<script setup>
import { computed, ref } from 'vue';
import { Link } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({rubric:Object,criteria:Array,levels:Array,matrix:Object});
const selected = ref({}); const maxLevel = computed(()=>Math.max(0,...props.levels.map(l=>Number(l.score_value))));
const maxScore = computed(()=>props.criteria.reduce((sum,c)=>sum+Number(c.weight),0));
const score = computed(()=>props.criteria.reduce((sum,c)=>{const level=props.levels.find(l=>l.id===Number(selected.value[c.id]));return sum+(maxLevel.value>0 ? Number(level?.score_value || 0)/maxLevel.value*Number(c.weight) : 0);},0));
</script>
<template><AssessmentLayout title="Rubric &amp; scoring preview" :subtitle="rubric.title"><template #action><a class="primary" :href="route('admin.rubrics.export',rubric.id)">Export JSON</a></template><section class="panel summary"><h2>{{ rubric.title }}</h2><p class="muted">{{ rubric.description || 'Pratinjau kriteria dan level rubrik.' }}</p><p class="score">Bobot {{ maxScore }} · Skor simulasi {{ score.toFixed(1) }} / {{ maxScore }}</p><p class="muted">Pilih level tiap kriteria untuk menghitung nilai.</p><Link :href="route('redesign.rubrics.edit',rubric.id)">Edit rubrik</Link></section><section class="panel"><h2>Rubric matrix</h2><div class="table-wrap"><table class="matrix"><thead><tr><th>Kriteria / bobot</th><th v-for="level in levels" :key="level.id">{{ level.label }} · {{ level.score_value }}</th></tr></thead><tbody><tr v-for="criterion in criteria" :key="criterion.id"><th>{{ criterion.name }} · {{ criterion.weight }}%</th><td v-for="level in levels" :key="level.id"><label class="cell" :class="{selected:Number(selected[criterion.id])===level.id}"><input v-model="selected[criterion.id]" type="radio" :name="`criterion-${criterion.id}`" :value="level.id" :aria-label="`${criterion.name}: ${level.label}`" /><span>{{ matrix?.[criterion.id]?.[level.id] || 'Belum ada deskripsi' }}</span></label></td></tr><tr v-if="!criteria.length"><td :colspan="levels.length+1" class="muted">Belum ada kriteria.</td></tr></tbody></table></div></section></AssessmentLayout></template>
<style scoped>.summary{margin-bottom:20px}.score{font-size:17px;font-weight:750;color:#00857c}.summary a{color:#007f78}.matrix{min-width:850px}.matrix th{min-width:170px}.matrix td{min-width:160px}.cell{display:flex;gap:8px;align-items:start;min-height:60px;cursor:pointer}.cell.selected{color:#007f78;font-weight:700}.cell input{width:auto!important;margin-top:3px}</style>
